$listFields=['responsabilites'=>'Responsabilités principales','activites'=>'Activités et tâches','competences'=>'Compétences requises','qualifications'=>'Qualifications et expériences','indicateurs_performance'=>'Indicateurs de performance','conditions_exercice'=>'Conditions et contraintes d’exercice'];
