    require_once __DIR__.'/../vendor/autoload.php';
    require_once __DIR__.'/includes/RhJobDescriptionExcel.php';
    RhJobDescriptionExcel::download($pdo,$selectedFunctionId);
}
$normalizeList=static function($value):?string{$items=is_array($value)?$value:preg_split('/\R+/',(string)$value);$items=array_values(array_filter(array_map(static fn($item)=>trim((string)$item),$items?:[]),static fn($item)=>$item!==''));return $items?implode("\n",$items):null;};
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
  if(!hash_equals((string)$_SESSION['rh_job_description_csrf'],(string)($_POST['_csrf']??'')))throw new RuntimeException('Session expirée.');
  $action=(string)($_POST['action']??'save');$id=(int)($_POST['id']??0);
  if($action==='import_xlsx'){
    require_once __DIR__.'/../vendor/autoload.php';
    require_once __DIR__.'/includes/RhJobDescriptionExcel.php';
    try { $count=RhJobDescriptionExcel::import($pdo,$_FILES['xlsx']??[],(int)($_SESSION['user_id']??0)); $message=$count.' fiche(s) importée(s) en brouillon.'; }
    catch (RuntimeException $ex) { if ($ex instanceof PDOException) throw new RuntimeException('Import annulé : données incompatibles avec le référentiel.'); throw $ex; }
    catch (Throwable $ex) { throw new RuntimeException('Import annulé : fichier Excel illisible ou incompatible.'); }
  }
  elseif($action==='archive'){$q=$pdo->prepare("UPDATE rh_fiches_poste SET statut='archivee',updated_by=? WHERE id=?");$q->execute([(int)($_SESSION['user_id']??0),$id]);$message='Fiche de poste archivée.';}
  else{$functionId=(int)($_POST['fonction_id']??0);$title=trim((string)($_POST['intitule']??''));if($functionId<1||$title==='')throw new RuntimeException('La fonction et l’intitulé sont obligatoires.');$values=['mission_principale'=>trim((string)($_POST['mission_principale']??''))?:null,'rattachement_hierarchique'=>trim((string)($_POST['rattachement_hierarchique']??''))?:null];foreach(array_keys($listFields) as $field)$values[$field]=$normalizeList($_POST[$field]??[]);$status=in_array((string)($_POST['statut']??''),['brouillon','active'],true)?(string)$_POST['statut']:'brouillon';if($status==='active'){$q=$pdo->prepare("UPDATE rh_fiches_poste SET statut='archivee',updated_by=? WHERE fonction_id=? AND statut='active' AND id<>?");$q->execute([(int)($_SESSION['user_id']??0),$functionId,$id]);}
   if($id>0){$q=$pdo->prepare('UPDATE rh_fiches_poste SET fonction_id=?,intitule=?,mission_principale=?,responsabilites=?,activites=?,competences=?,qualifications=?,indicateurs_performance=?,rattachement_hierarchique=?,conditions_exercice=?,version=?,statut=?,date_effet=?,updated_by=? WHERE id=?');$q->execute([$functionId,$title,$values['mission_principale'],$values['responsabilites'],$values['activites'],$values['competences'],$values['qualifications'],$values['indicateurs_performance'],$values['rattachement_hierarchique'],$values['conditions_exercice'],trim((string)($_POST['version']??'1.0'))?:'1.0',$status,$_POST['date_effet']?:null,(int)($_SESSION['user_id']??0),$id]);$message='Fiche de poste mise à jour.';}
   else{$q=$pdo->prepare('INSERT INTO rh_fiches_poste(fonction_id,intitule,mission_principale,responsabilites,activites,competences,qualifications,indicateurs_performance,rattachement_hierarchique,conditions_exercice,version,statut,date_effet,created_by,updated_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$uid=(int)($_SESSION['user_id']??0);$q->execute([$functionId,$title,$values['mission_principale'],$values['responsabilites'],$values['activites'],$values['competences'],$values['qualifications'],$values['indicateurs_performance'],$values['rattachement_hierarchique'],$values['conditions_exercice'],trim((string)($_POST['version']??'1.0'))?:'1.0',$status,$_POST['date_effet']?:null,$uid,$uid]);$message='Fiche de poste créée.';}
  }
 }catch(Throwable $e){$error=$e->getMessage();}
}
$functions=$pdo->query('SELECT id_fonction id,lib_fonction label FROM fonction ORDER BY lib_fonction')->fetchAll(PDO::FETCH_ASSOC);$edit=null;if($editId){$q=$pdo->prepare('SELECT * FROM rh_fiches_poste WHERE id=?');$q->execute([$editId]);$edit=$q->fetch(PDO::FETCH_ASSOC)?:null;}$rows=$pdo->query('SELECT fp.*,f.lib_fonction fonction_label,(SELECT COUNT(*) FROM personnel p WHERE p.fonction_id=fp.fonction_id AND COALESCE(NULLIF(p.personnel_category,\'\'),\'interne\')=\'interne\' AND (p.date_sortie IS NULL OR p.date_sortie=\'0000-00-00\')) effectif FROM rh_fiches_poste fp JOIN fonction f ON f.id_fonction=fp.fonction_id ORDER BY FIELD(fp.statut,\'active\',\'brouillon\',\'archivee\'),f.lib_fonction,fp.updated_at DESC')->fetchAll(PDO::FETCH_ASSOC);
$pageTitle='Fiches de poste';$activeMenu='rh';require __DIR__.'/../decaissement/includes/header.php';require __DIR__.'/../decaissement/includes/navbar.php';$e=fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');
?>
<main class="mx-auto max-w-7xl px-4 py-8"><header class="rounded-[30px] bg-[var(--brand-primary)] p-8 text-white" style="border-bottom:4px solid var(--brand-accent)"><div class="mb-5 flex flex-wrap items-center justify-between gap-4"><?php if (!empty($layoutBrandLogoUrl)): ?><img src="<?=$e($layoutBrandLogoUrl)?>" alt="<?=$e($layoutCompanyBranding['company_name'])?>" class="h-20 w-40 rounded-xl bg-white p-3 object-contain"><?php else: ?><span class="font-bold"><?=$e($layoutCompanyBranding['company_name'])?></span><?php endif;?><a href="liste_personnel_rh.php?scope=all" class="rounded-xl border border-white/40 px-4 py-2 text-sm font-bold text-white"><i class="fas fa-arrow-left mr-2"></i>Liste du personnel</a></div><p class="text-xs font-black uppercase tracking-[.22em] text-white">Ressources humaines</p><h1 class="mt-2 text-3xl font-black">Fiches de poste</h1><p class="mt-2 text-slate-300">Formalisez les missions, responsabilités, compétences et critères d’évaluation de chaque fonction.</p></header><section class="mt-6 rounded-3xl border border-slate-200 bg-white p-6 shadow-sm">
<div class="flex items-center gap-3"><span class="grid h-12 w-12 place-items-center rounded-2xl bg-emerald-50 text-xl text-emerald-700"><i class="fas fa-file-excel"></i></span><div><h2 class="text-xl font-bold">Importation Excel</h2><p class="text-sm text-slate-500">Créez plusieurs fiches en une seule opération.</p></div></div>
<div class="mt-5 grid gap-5 md:grid-cols-2">
<div class="rounded-2xl bg-slate-50 p-5"><p class="text-xs font-bold uppercase tracking-wider text-slate-500">Étape 01</p><h3 class="mt-2 font-bold">Préparer le fichier</h3><p class="mt-2 text-sm leading-6 text-slate-600">Le modèle contient deux exemples complets, le référentiel des fonctions et les instructions.</p><a class="mt-4 inline-flex items-center rounded-xl border border-slate-300 bg-white px-4 py-3 font-bold" href="?download=xlsx&amp;fonction_id=<?=$selectedFunctionId?>"><i class="fas fa-download mr-2"></i>Télécharger le modèle Excel</a></div>
<form id="rh-excel-import" method="post" enctype="multipart/form-data" class="rounded-2xl border border-slate-200 p-5"><input type="hidden" name="_csrf" value="<?=$e($_SESSION['rh_job_description_csrf'])?>"><input type="hidden" name="action" value="import_xlsx"><p class="text-xs font-bold uppercase tracking-wider text-slate-500">Étape 02</p><h3 class="mt-2 font-bold">Déposer le fichier</h3><label id="rh-dropzone" class="relative mt-3 flex min-h-36 cursor-pointer flex-col items-center justify-center rounded-2xl border-2 border-dashed border-slate-300 bg-slate-50 p-4 text-center transition"><i class="fas fa-cloud-upload-alt mb-2 text-3xl" style="color:var(--brand-primary)"></i><span class="font-bold">Glissez-déposez votre fichier ici</span><span class="mt-1 text-sm text-slate-500">ou cliquez pour parcourir · XLSX, 2 Mo max.</span><input id="rh-xlsx" type="file" name="xlsx" accept=".xlsx" required aria-label="Choisir un fichier Excel" class="absolute inset-0 h-full w-full cursor-pointer opacity-0"></label><p id="rh-file-status" role="status" class="mt-2 break-all text-sm text-slate-600">Aucun fichier sélectionné</p><div class="mt-4 flex flex-wrap gap-2"><button id="rh-import-submit" class="rounded-xl bg-[var(--brand-primary)] px-4 py-3 font-bold text-white"><i class="fas fa-upload mr-2"></i>Importer en brouillon</button><button id="rh-file-clear" type="button" hidden class="rounded-xl border px-4 py-3 font-bold">Retirer</button></div><p class="mt-3 text-xs text-slate-500">500 fiches maximum. Aucun écrasement des fiches existantes.</p></form></div></section>
<style>
#rh-dropzone:focus-within,#rh-dropzone.is-dragging{outline:2px solid var(--brand-primary);outline-offset:3px;background:#eef2ff}
#rh-job-form input:not([type=hidden]),#rh-job-form select,#rh-job-form textarea{background:#f8fafc;border:1px solid #cbd5e1;transition:border-color .15s,box-shadow .15s;font-weight:400}
#rh-job-form input:focus,#rh-job-form select:focus,#rh-job-form textarea:focus{outline:2px solid var(--brand-primary);outline-offset:2px;background:white}
#rh-job-form textarea{resize:vertical;min-height:100px}
</style>
<script>
(function(){
const input=document.getElementById('rh-xlsx'),zone=document.getElementById('rh-dropzone'),status=document.getElementById('rh-file-status'),clear=document.getElementById('rh-file-clear'),form=document.getElementById('rh-excel-import'),submit=document.getElementById('rh-import-submit');
function refresh(){const f=input.files[0];const valid=!!f&&/\.xlsx$/i.test(f.name)&&f.size<=2097152;input.setCustomValidity(f&&!valid?'Choisissez un fichier XLSX de 2 Mo maximum.':'');status.textContent=f?(valid?f.name+' · '+Math.ceil(f.size/1024)+' Ko':'Fichier invalide : XLSX, 2 Mo maximum.'):'Aucun fichier sélectionné';clear.hidden=!f;submit.disabled=!valid;submit.style.opacity=valid?'1':'.55';}
input.addEventListener('change',refresh);clear.addEventListener('click',()=>{input.value='';refresh();input.focus();});
zone.addEventListener('dragover',e=>{e.preventDefault();zone.classList.add('is-dragging');});
zone.addEventListener('dragleave',()=>zone.classList.remove('is-dragging'));
zone.addEventListener('drop',e=>{e.preventDefault();zone.classList.remove('is-dragging');if(e.dataTransfer.files.length!==1){status.textContent='Déposez un seul fichier Excel.';return;}try{input.files=e.dataTransfer.files;refresh();}catch(err){status.textContent='Utilisez le bouton de sélection du fichier.';}});
form.addEventListener('submit',()=>{submit.disabled=true;submit.textContent='Importation en cours…';});refresh();
})();
</script><?php if($message):?><div class="mt-5 rounded-2xl bg-emerald-50 p-4 font-bold text-emerald-800"><?=$e($message)?></div><?php endif;?><?php if($error):?><div class="mt-5 rounded-2xl bg-rose-50 p-4 font-bold text-rose-800"><?=$e($error)?></div><?php endif;?><div class="mt-6 grid gap-6 xl:grid-cols-[1.15fr_.85fr]"><section class="rounded-[28px] border bg-white p-6"><h2 class="text-xl font-black"><?=$edit?'Modifier la fiche':'Nouvelle fiche de poste'?></h2><form id="rh-job-form" method="post" class="mt-5 space-y-5"><input type="hidden" name="_csrf" value="<?=$e($_SESSION['rh_job_description_csrf'])?>"><input type="hidden" name="id" value="<?=(int)($edit['id']??0)?>"><div class="rounded-2xl bg-slate-50 p-4"><h3 class="font-bold" style="color:var(--brand-primary)">01 · Identification du poste</h3><p class="mt-1 text-sm text-slate-500">Fonction, intitulé, version et rattachement.</p></div><div class="grid gap-4 md:grid-cols-2"><label class="font-bold">Fonction<select required name="fonction_id" class="mt-2 w-full rounded-2xl border p-3"><option value="">Sélectionner</option><?php foreach($functions as $function):?><option value="<?=(int)$function['id']?>" <?=((int)($edit['fonction_id']??$selectedFunctionId)===(int)$function['id'])?'selected':''?>><?=$e($function['label'])?></option><?php endforeach;?></select></label><label class="font-bold">Intitulé<input required name="intitule" value="<?=$e($edit['intitule']??'')?>" class="mt-2 w-full rounded-2xl border p-3"></label><label class="font-bold">Version<input name="version" value="<?=$e($edit['version']??'1.0')?>" class="mt-2 w-full rounded-2xl border p-3"></label><label class="font-bold">Date d’effet<input type="date" name="date_effet" value="<?=$e($edit['date_effet']??'')?>" class="mt-2 w-full rounded-2xl border p-3"></label><label class="font-bold md:col-span-2">Rattachement hiérarchique<input name="rattachement_hierarchique" value="<?=$e($edit['rattachement_hierarchique']??'')?>" class="mt-2 w-full rounded-2xl border p-3" placeholder="Ex. Directeur technique"></label></div><div class="rounded-2xl bg-slate-50 p-4"><h3 class="font-bold" style="color:var(--brand-primary)">02 · Missions et compétences</h3><p class="mt-1 text-sm text-slate-500">Décrivez le poste et ses critères d’évaluation.</p></div><?php foreach(['mission_principale'=>'Mission principale','responsabilites'=>'Responsabilités principales (une par ligne)','activites'=>'Activités et tâches (une par ligne)','competences'=>'Compétences requises (une par ligne)','qualifications'=>'Qualifications et expérience','indicateurs_performance'=>'Indicateurs de performance (un par ligne)','conditions_exercice'=>'Conditions et contraintes d’exercice'] as $field=>$label):?><label class="block font-bold"><?=$label?><textarea name="<?=$field?>" rows="3" class="mt-2 w-full rounded-2xl border p-3"><?=$e($edit[$field]??'')?></textarea></label><?php endforeach;?><label class="block font-bold">Statut<select name="statut" class="mt-2 w-full rounded-2xl border p-3"><option value="brouillon" <?=($edit['statut']??'')==='brouillon'?'selected':''?>>Brouillon</option><option value="active" <?=($edit['statut']??'')==='active'?'selected':''?>>Active et applicable</option></select></label><div class="flex gap-3"><button class="rounded-xl bg-[var(--brand-primary)] px-5 py-3 font-black text-white">Enregistrer</button><?php if($edit):?><a href="fiches_poste_rh.php" class="rounded-xl border px-5 py-3 font-bold">Annuler</a><?php endif;?></div></form></section><section class="space-y-4"><h2 class="text-xl font-black">Référentiel</h2><?php foreach($rows as $row):?><article class="rounded-[24px] border bg-white p-5"><div class="flex justify-between gap-3"><div><small class="font-black uppercase text-slate-600">Version <?=$e($row['version'])?> · <?=$e($row['statut'])?></small><h3 class="mt-1 font-black"><?=$e($row['intitule'])?></h3><p class="text-sm text-slate-500"><?=$e($row['fonction_label'])?> · <?=(int)$row['effectif']?> titulaire(s) interne(s)</p></div><a href="?edit=<?=(int)$row['id']?>" class="h-fit rounded-xl border px-3 py-2 font-bold">Modifier</a></div><p class="mt-3 text-sm text-slate-600"><?=$e($row['mission_principale']?:'Mission à renseigner')?></p><?php if($row['statut']!=='archivee'):?><form method="post" class="mt-3"><input type="hidden" name="_csrf" value="<?=$e($_SESSION['rh_job_description_csrf'])?>"><input type="hidden" name="id" value="<?=(int)$row['id']?>"><button name="action" value="archive" class="text-sm font-bold text-rose-700">Archiver</button></form><?php endif;?></article><?php endforeach;?><?php if(!$rows):?><div class="rounded-2xl border border-dashed bg-white p-8 text-center text-slate-500">Aucune fiche de poste enregistrée.</div><?php endif;?></section></div></main><?php require __DIR__.'/../decaissement/includes/footer.php';?>
